import Foundation

/// Static Unicode/Shift_JIS character mapping, generated from the WHATWG decoder.
/// Retains the first code point mapping, exactly as SpecQR's public Kanji mode.
internal enum KanjiMap {
   static let codes: [UInt32: UInt16] = {
      let data = Array(
         Data(
            base64Encoded:
               ""
         )!)
      var result: [UInt32: UInt16] = [:]
      result.reserveCapacity(data.count / 4)
      for offset in stride(from: 0, to: data.count, by: 4) {
         let scalar = UInt32(data[offset]) << 8 | UInt32(data[offset + 1])
         let code = UInt16(data[offset + 2]) << 8 | UInt16(data[offset + 3])
         result[scalar] = code
      }
      return result
   }()
   static func value(_ scalar: Unicode.Scalar) -> Int? {
      guard let code = codes[scalar.value] else { return nil }
      let adjusted = Int(code) - (code <= 0x9FFC ? 0x8140 : 0xC140)
      return (adjusted >> 8) * 0xC0 + (adjusted & 255)
   }
}
